def schema_drift(expected, actual):
    def leaf_paths(obj, path):
        if isinstance(obj, dict):
            for key, value in obj.items():
                yield from leaf_paths(value, path + [key])
        else:
            yield ".".join(path)

    def compare(e, a, path):
        if isinstance(e, dict) and isinstance(a, dict):
            drifts = set()
            for key in e.keys() - a.keys():
                drifts.update(leaf_paths(e[key], path + [key]))
            for key in a.keys() - e.keys():
                drifts.update(leaf_paths(a[key], path + [key]))
            for key in e.keys() & a.keys():
                drifts.update(compare(e[key], a[key], path + [key]))
            return drifts

        if e != a:
            return {".".join(path)}
        return set()

    return sorted(compare(expected, actual, []))

def bounded_batches(items, max_rows):
    if max_rows <= 0:
        raise ValueError("max_rows must be positive")

    batches = []
    current_batch = []
    current_rows = 0

    for item in items:
        _, row_count = item

        if row_count > max_rows:
            if current_batch:
                batches.append(current_batch)
                current_batch = []
                current_rows = 0
            batches.append([item])
        else:
            if current_rows + row_count > max_rows:
                batches.append(current_batch)
                current_batch = []
                current_rows = 0
            current_batch.append(item)
            current_rows += row_count

    if current_batch:
        batches.append(current_batch)

    return batches

