def merge_payload_ranges(items):
    sorted_items = []
    for start, end, payload in items:
        if start > end:
            raise ValueError("start must be <= end")
        sorted_items.append((start, end, payload))

    sorted_items.sort(key=lambda x: (x[0], x[1]))

    try:
        by_payload = {}
        for start, end, payload in sorted_items:
            by_payload.setdefault(payload, []).append((start, end))
        groups = [(payload, intervals) for payload, intervals in by_payload.items()]
    except TypeError:
        groups = []
        for start, end, payload in sorted_items:
            for group in groups:
                if group[0] == payload:
                    group[1].append((start, end))
                    break
            else:
                groups.append([payload, [(start, end)]])

    merged = []
    for payload, intervals in groups:
        cur_start, cur_end = intervals[0]
        for start, end in intervals[1:]:
            if start <= cur_end:
                if end > cur_end:
                    cur_end = end
            else:
                merged.append([cur_start, cur_end, payload])
                cur_start, cur_end = start, end
        merged.append([cur_start, cur_end, payload])

    merged.sort(key=lambda x: (x[0], x[1]))
    return merged
